            used_tool,
            contains_answer,
            starts_capitalized,
            word_count,
        ],
        weights=[0.25, -0.3, 0.2, 0.15, 0.1, 0.0],
    )

    dataset = Dataset.from_list([
        {"question": "stub", "answer": "stub"}
