    # Wrap the rubric's scorer to implement EXCLUSION RULE
    original_scorer = env.rubric.scorer

    def exclusion_aware_scorer(completion, answer, info):
        """Apply EXCLUSION RULE: zero weighted criteria if excluded."""
        excluded = info.get("excluded", False) is True

        # Get all metric values
        metrics = {}
        for func in env.rubric.funcs:
            metrics[func.__name__] = func(
                completion=completion, answer=answer, info=info
            )

        # If excluded, zero out weighted criteria (keep zero-weight diagnostic)
        if excluded:
            for i, func in enumerate(env.rubric.funcs):
                if env.rubric.weights[i] != 0.0:
                    metrics[func.__name__] = 0.0

        # Compute weighted sum
        reward = sum(
            metrics[func.__name__] * weight
            for func, weight in zip(env.rubric.funcs, env.rubric.weights)
        )

        return reward, metrics

    env.rubric.scorer = exclusion_aware_scorer

    return env
